// Base case: if tree is empty, create a new node
if (root == nullptr) {
    root = new TreeNode(item);
    return;
}

// Recursive case: insert into left or right subtree
if (item < root->value) {
    avlInsert(root->left, item);
} else if (item > root->value) {
    avlInsert(root->right, item);
} else {
    // No duplicate values allowed
    return;
}

// Balance the tree after insertion
int balanceFactor = getBalanceFactor(root);

// Left-left case
if (balanceFactor > 1 && item < root->left->value) {
    root = rotateRight(root);
}

// Left-right case
if (balanceFactor > 1 && item > root->left->value) {
    root->left = rotateLeft(root->left);
    root = rotateRight(root);
}

// Right-right case
if (balanceFactor < -1 && item > root->right->value) {
    root = rotateLeft(root);
}

// Right-left case
if (balanceFactor < -1 && item < root->right->value) {
    root->right = rotateRight(root->right);
    root = rotateLeft(root);
}

// Update height of current node
root->height = std::max(getHeight(root->left), getHeight(root->right)) + 1;

